import {uid,calculate,money} from './core.js';
import {esc,btn,field,select} from './views.js';
import {ticketMarkup,returnMarkup,cashCutMarkup} from './commerce-views.js';
import {recordSale,recordPurchase,recordProduction,recordAdjustment,removeInventory,salePreview,stockItem,setPrinter,claimTicket,peekTicket,saleReturns,saleReturnedQuantities,recordReturn,recordCashCut,cashCutReport} from './workshop.js';
import {ticketDocument,returnDocument,cutDocument,standaloneDocument,printDocument} from './documents.js';
import * as storage from './storage.js';
export function commerceController(c){
 const {ui,render,persist,flush,showModal,closeModal,toast}=c,S=c.state,$=id=>document.getElementById(id);
 let busy=false,itemDraft=null,productionId=null;
 const valid=()=>{if([...document.querySelectorAll('#modal-root input')].some(x=>!x.checkValidity()))throw Error('Revisa los campos del formulario.');};
 const allItems=()=>[...S().materials.filter(x=>!x.retired).map(x=>({...x,kind:'material',unit:'g'})),...S().supplies.filter(x=>!x.retired).map(x=>({...x,kind:'supply'})),...S().products.filter(x=>!x.retired).map(x=>({...x,kind:'product'})),...S().assets.filter(x=>!x.retired).map(x=>({...x,kind:'asset'}))];
 const draft=id=> (S().posDrafts||[]).find(d=>d.id===id);
 const currentDraft=()=>draft(ui.draftId);
 const brand=()=>({...S().settings,currency:S().currency});
 const openDrafts=()=>(S().posDrafts||[]).filter(d=>d.cart?.length);
 const draftTotal=d=>{try{return salePreview(S(),d.cart,d.reserve!==false).total;}catch{return d.cart.reduce((n,l)=>n+(+l.qty||0)*(+l.unitPrice||0),0);}};
 function loadDraft(d){ui.draftId=d?.id||null;ui.cart=d?structuredClone(d.cart):[];ui.posCustomer=d?.customer||'';ui.saleNote=d?.note||'';ui.saleReserve=d?.reserve!==false;ui.posFresh=false;}
 function enterPOS(){if(!Array.isArray(S().posDrafts))S().posDrafts=[];if(ui.posFresh){ui.posFresh=false;return;}const active=currentDraft();if(active&&active.cart?.length)return;const recent=openDrafts().slice().sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||'')))[0];if(recent)loadDraft(recent);else loadDraft(null);}
 function keepDraft(){const d=currentDraft();if(d){d.cart=structuredClone(ui.cart||[]);d.customer=ui.posCustomer||'';d.note=ui.saleNote||'';d.reserve=ui.saleReserve!==false;d.updatedAt=new Date().toISOString();}persist();}
 function ensureDraft(){let d=currentDraft();if(d){d.cart=structuredClone(ui.cart||[]);return d;}d={id:uid(),number:claimTicket(S()),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),customer:ui.posCustomer||'',note:ui.saleNote||'',reserve:ui.saleReserve!==false,cart:structuredClone(ui.cart||[])};S().posDrafts.push(d);ui.draftId=d.id;return d;}
 function dropEmptyDraft(){if(!ui.cart.length&&currentDraft()){S().posDrafts=S().posDrafts.filter(d=>d.id!==ui.draftId);ui.draftId=null;ui.posCustomer='';ui.saleNote='';}}
 async function commit(fn,after){if(busy)return;busy=true;const before=structuredClone(S());try{const result=fn();await flush();closeModal();render();if(after)after(result);else toast('Inventario y movimiento guardados.');return result;}catch(e){c.setState(before);render();throw e;}finally{busy=false;}}
 function itemDialog(kind,id){const old=stockItem(S(),kind,id),item=old||{id:uid(),name:'',sku:'',stock:0,minStock:kind==='product'?3:0,unitCost:0,price:0,unit:'pzas',packUnits:1,category:'Otros'};itemDraft={kind,id:item.id};const sources=[['','Sin modelo asociado'],...S().boxes.filter(b=>!b.archived).flatMap(b=>b.objects.map(o=>[b.id+'|'+o.id,b.name+' · '+o.name]))];showModal(old?'Editar '+item.name:kind==='product'?'Nuevo producto terminado':'Nuevo artículo del taller',`<div class="form-grid">${field('Nombre',item.name,'id="stock-name" required','text')}${kind==='product'?field('SKU / código',item.sku,'id="stock-sku"','text'):select('Categoría',[['Herramientas','Herramientas'],['Equipo','Equipo'],['Otros','Otros']],item.category,'id="stock-category"')}${field('Existencias físicas',item.stock,`id="stock-qty" min="0" ${kind==='product'?'step="1"':''}`)}${field('Avisar al quedar esta cantidad',item.minStock,'id="stock-min"')}${field('Costo por unidad',item.unitCost,'id="stock-cost"')}${kind==='product'?field('Precio de venta',item.price,'id="stock-price"'):select('Unidad',[['pzas','Piezas'],['g','Gramos'],['ml','Mililitros'],['m','Metros']],item.unit,'id="stock-unit"')}${kind==='product'?select('Objeto de la estantería (opcional)',sources,item.sourceBoxId?item.sourceBoxId+'|'+item.sourceObjectId:'','id="stock-source"'):field('Contenido del paquete',item.packUnits,'id="stock-pack" min="0.001"')}</div><p class="short-note">Registra aquí lo que ya tienes físicamente. El conteo inicial o su corrección no registra una compra. Para fabricar más piezas, usa Registrar producción; para reponer material comprado, usa Registrar compra.</p>`,btn('Cancelar','close-modal')+btn('Guardar artículo','save-stock-item','check','primary'));}
 function purchaseDialog(kind,id){const items=allItems();if(!items.length)throw Error('Agrega un artículo al inventario antes de comprarlo.');const item=items.find(x=>x.kind===kind&&x.id===id)||items[0],units=item.kind==='material'?item.spoolGrams:item.packUnits;showModal('Registrar compra',`<div class="form-grid">${select('Artículo',items.map(x=>[x.kind+':'+x.id,`${({material:'Filamento',supply:'Insumo',product:'Producto',asset:'Equipo / otro'})[x.kind]} · ${x.name}`]),item.kind+':'+item.id,'id="purchase-item"')}${field('Paquetes / bobinas',1,'id="purchase-packs" min="1" step="1"')}${field(`Contenido por paquete (${item.unit})`,units,'id="purchase-units" min="0.001"')}${field('Importe total pagado',item.kind==='material'?item.price:units*item.unitCost,'id="purchase-total"')}${field('Proveedor / referencia / nota','','id="purchase-note"','text')}</div><p class="short-note">Se suma el contenido al inventario y el total pagado se descuenta del saldo del taller. Revisa el importe total al cambiar el número de paquetes. El costo para presupuestar se puede editar en cada artículo.</p>`,btn('Cancelar','close-modal')+btn('Registrar compra','confirm-purchase','check','primary'));}
 function showTicket(t){showModal('Venta registrada · '+(t.ticket||''),ticketMarkup(t,S().settings,saleReturns(S(),t.id)),btn('Imprimir','print-ticket','printer',`data-id="${esc(t.id)}"`)+btn('Ticket virtual','export-ticket-html','download','',`data-id="${esc(t.id)}"`)+btn('Texto','export-ticket','file','',`data-id="${esc(t.id)}"`)+btn('Cerrar','close-modal','','primary'));}
 function showReturn(t){const sale=S().ledger.find(x=>x.id===t.saleId);showModal('Devolución registrada · '+t.ticket,returnMarkup(t,sale,S().settings),btn('Imprimir','print-return','printer',`data-id="${esc(t.id)}"`)+btn('Virtual','export-return-html','download','',`data-id="${esc(t.id)}"`)+btn('Cerrar','close-modal','','primary'));}
 function showCut(cut){showModal((cut.type==='full'?'Corte total':'Corte parcial')+' · '+cut.number,cashCutMarkup(cut,brand()),btn('Imprimir','print-cut','printer',`data-id="${esc(cut.id)}"`)+btn('Corte virtual','export-cut-html','download','',`data-id="${esc(cut.id)}"`)+btn('Cerrar','close-modal','','primary'));}
 function checkout(){ui.posCustomer=$('pos-customer')?.value||ui.posCustomer||'';ui.saleNote=$('pos-note')?.value||ui.saleNote||'';keepDraft();const p=salePreview(S(),ui.cart,ui.saleReserve!==false);if(p.shortages.length)throw Error('Revisa el stock antes de cobrar.');const d=currentDraft();showModal('Cobrar venta · '+(d?.number||peekTicket(S())),`<div class="checkout-total"><span>Total del ticket</span><strong>${money(p.total,S().currency)}</strong></div><div class="form-grid section-space">${select('Forma de pago',[['efectivo','Efectivo'],['transferencia','Transferencia'],['tarjeta','Tarjeta (registro)']],'efectivo','id="payment-method"')}${field('Importe recibido',p.total.toFixed(2),'id="payment-received" min="0" step="0.01"')}</div><div class="between section-space"><span>Cambio</span><strong id="payment-change">${money(0,S().currency)}</strong></div><p class="short-note">Al confirmar se guarda el ticket, se registra el cobro y se descuenta el stock correspondiente. Las tarjetas y transferencias se registran aquí después de cobrarlas por tu medio habitual.</p>`,btn('Volver al ticket','close-modal')+btn('Confirmar cobro','confirm-checkout','check','primary'));}
 function productionPlan(qty){const p=stockItem(S(),'product',productionId);try{const plan=salePreview(S(),[{boxId:p.sourceBoxId,objectId:p.sourceObjectId,qty,unitPrice:0}],true);return {ok:!plan.shortages.length,html:`<div class="table-wrap"><table><thead><tr><th>Material</th><th>Consumo con reserva</th><th>Disponible</th></tr></thead><tbody>${plan.movements.map(m=>`<tr class="${m.shortage?'danger-text':''}"><td>${esc(m.name)}</td><td>${m.units.toFixed(2)} ${esc(m.unit)}</td><td>${m.available.toFixed(2)}</td></tr>`).join('')}</tbody></table></div><p class="short-note">Costo estimado de la producción: ${money(plan.cost,S().currency)}.</p>${plan.shortages.length?'<p class="danger-text">Falta stock para completar esta producción.</p>':''}`};}catch(e){return {ok:false,html:`<p class="danger-text">${esc(e.message)}</p>`};}}
 function returnDialog(saleId){
  const sale=S().ledger.find(t=>t.id===saleId&&t.type==='sale');if(!sale||sale.voided)throw Error('La venta no está disponible.');ui.returnSaleId=saleId;
  const prior=saleReturnedQuantities(S(),saleId);const rows=sale.lines.map((l,i)=>{const left=l.qty-(prior[i]||0);return {l,i,left,requested:i===0?left:0};}).filter(x=>x.left>0);
  if(!rows.length)throw Error('Todas las piezas de esta venta ya fueron devueltas.');
  showModal('Devolución · '+(sale.ticket||''),`<p>Registra solo las piezas que vuelven al taller. El stock se repone y el importe se descuenta de la caja sin borrar la venta original.</p><div class="table-wrap"><table><thead><tr><th>Artículo</th><th>Vendidas</th><th>Disponibles</th><th>Devolver</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.l.name)}</td><td>${x.l.qty}</td><td>${x.left}</td><td><input class="table-input" type="number" min="0" max="${x.left}" step="1" value="${x.requested}" data-return-line="${x.i}"></td></tr>`).join('')}</tbody></table></div><div class="form-grid section-space">${select('Forma de reembolso',[['efectivo','Efectivo'],['transferencia','Transferencia'],['tarjeta','Tarjeta / terminal'],['saldo','Saldo a favor'],['nota_credito','Nota de crédito']],'efectivo','id="return-method"')}${field('Nota / motivo','','id="return-note"','text')}</div><p class="short-note">Puedes devolver una parte ahora y el resto después. Cada devolución queda con su propio folio e historial.</p>`,btn('Cancelar','close-modal')+btn('Registrar devolución','confirm-return','back','primary'));
 }
 function openCut(type){const report=cashCutReport(S(),{type,to:new Date().toISOString()});const preview={number:'VISTA PREVIA',type,date:report.to,from:report.from,to:report.to,note:'',report};showModal(type==='full'?'Corte de caja total':'Corte parcial',cashCutMarkup(preview,brand())+`<label class="field section-space">Nota del corte<input id="cut-note" placeholder="Turno, responsable o referencia"></label><p class="short-note">${type==='full'?'El corte total guarda el periodo y comienza uno nuevo. No borra ventas ni movimientos.':'El corte parcial solo genera un reporte del periodo actual; no reinicia nada.'}</p>`,btn('Cancelar','close-modal')+btn(type==='full'?'Guardar corte total':'Guardar corte parcial','confirm-cut','check','primary',`data-type="${type}"`));}
 async function downloadHtml(name,html){await storage.download(new Blob([html],{type:'text/html;charset=utf-8'}),name);}
 const ledgerSale=id=>S().ledger.find(t=>t.id===id);
 const actions={
  'inventory-tab':el=>{ui.inventoryTab=el.dataset.tab;render();},'new-product':()=>itemDialog('product'),'new-asset':()=>itemDialog('asset'),'edit-stock-item':el=>itemDialog(el.dataset.kind,el.dataset.id),
  'save-stock-item':()=>{valid();const {kind,id}=itemDraft,old=stockItem(S(),kind,id),qty=+$('stock-qty').value,name=$('stock-name').value.trim();if(!name)throw Error('Escribe el nombre del artículo.');if(kind==='product'&&!Number.isInteger(qty))throw Error('Las piezas terminadas se cuentan en unidades enteras.');const item={...(old||{}),id,name,stock:old?.stock||0,minStock:+$('stock-min').value,unitCost:+$('stock-cost').value,unit:kind==='product'?'pzas':$('stock-unit').value,packUnits:kind==='product'?1:+$('stock-pack').value};if(kind==='product'){item.sku=$('stock-sku').value.trim();item.price=+$('stock-price').value;[item.sourceBoxId,item.sourceObjectId]=$('stock-source').value.split('|');}else item.category=$('stock-category').value;return commit(()=>{const list=kind==='product'?S().products:S().assets;if(old)Object.assign(old,item);else list.push(item);recordAdjustment(S(),kind,id,qty,old?'Ajuste de conteo':'Conteo inicial');});},
  'delete-stock-item':el=>{ui.deletePhysical={kind:el.dataset.kind,id:el.dataset.id};showModal('Retirar artículo del inventario','<p>El artículo se retirará de la lista activa. Si tiene movimientos, se conservará su historial y podrás restaurarlo.</p>',btn('Cancelar','close-modal')+btn('Retirar','confirm-delete-physical','trash','danger'));},
  'confirm-delete-physical':()=>commit(()=>removeInventory(S(),ui.deletePhysical.kind,ui.deletePhysical.id)),
  'edit-printer-inventory':el=>{setPrinter(S(),el.dataset.id);ui.view='settings';persist();render();},
  'purchase':el=>purchaseDialog(el.dataset.kind,el.dataset.id),'confirm-purchase':()=>{valid();const[kind,id]=$('purchase-item').value.split(':');const input={kind,id,packs:+$('purchase-packs').value,packUnits:+$('purchase-units').value,total:+$('purchase-total').value,note:$('purchase-note').value};return commit(()=>recordPurchase(S(),input));},
  'produce-product':el=>{productionId=el.dataset.id;const p=stockItem(S(),'product',productionId),plan=productionPlan(1);showModal('Registrar producción · '+p.name,`${field('Piezas terminadas que agregas',1,'id="production-qty" min="1" step="1"')}<div id="production-plan" class="section-space">${plan.html}</div>${field('Referencia / nota','','id="production-note"','text')}<p class="short-note">Registra una producción ya realizada. Esto consume sus materiales y agrega producto terminado. Vender ese producto después no vuelve a consumir esos materiales.</p>`,btn('Cancelar','close-modal')+btn('Registrar producción','confirm-production','layers','primary',plan.ok?'':'disabled'));},
  'confirm-production':()=>{valid();const input={productId:productionId,qty:+$('production-qty').value,note:$('production-note').value};return commit(()=>recordProduction(S(),input));},
  'pos-tab':el=>{ui.posTab=el.dataset.tab;render();},'pos-source':el=>{ui.posSource=el.dataset.source;render();},
  'new-sale':()=>{ui.cart=[];ui.draftId=null;ui.saleNote='';ui.posCustomer='';ui.saleReserve=true;ui.posTab='sale';ui.posFresh=true;ui.view='pos';render();},
  'open-draft':el=>{const d=draft(el.dataset.id);if(!d)throw Error('Ese ticket ya no está abierto.');loadDraft(d);render();toast('Ticket '+d.number+' recuperado.');},
  'discard-draft':el=>{const d=draft(el.dataset.id);if(!d)throw Error('Ticket no disponible.');showModal('Descartar ticket '+d.number,`<p>Se quitará de los tickets abiertos. No hay cobro ni movimiento de inventario. Esta acción no se puede deshacer.</p>`,btn('Cancelar','close-modal')+btn('Descartar ticket','confirm-discard-draft','trash','danger',`data-id="${esc(d.id)}"`));},
  'confirm-discard-draft':el=>{S().posDrafts=S().posDrafts.filter(d=>d.id!==el.dataset.id);if(ui.draftId===el.dataset.id)loadDraft(null);closeModal();persist();render();toast('Ticket descartado.');},
  'pos-add':el=>{ui.cart??=[];const kind=el.dataset.kind,id=el.dataset.id;let line;if(kind==='product'){const p=stockItem(S(),'product',id);line={kind:'product',productId:id,name:p.name,qty:1,unitPrice:p.price,requestedColor:''};}else{const b=S().boxes.find(b=>b.id===el.dataset.box),o=b?.objects.find(o=>o.id===id);if(!o)throw Error('No existe ese objeto.');const calc=calculate(o,S().materials,S().settings);if(calc.missing){ui.selected=b.id;ui.objectId=o.id;ui.view='print';render();toast('Lamina el objeto y abre su G-code en el puente para obtener tiempo, gramos y precio.');return;}line={kind:'model',boxId:b.id,objectId:o.id,name:o.name,qty:1,unitPrice:Math.round(calc.price*100)/100,colors:calc.requirements.rows.map(r=>r.id)};}const existing=ui.cart.find(l=>kind==='product'?l.kind==='product'&&l.productId===id:l.kind!=='product'&&l.objectId===id&&l.boxId===line.boxId);if(existing)existing.qty++;else ui.cart.push(line);ensureDraft();keepDraft();render();},
  'pos-remove':el=>{ui.cart.splice(+el.dataset.index,1);dropEmptyDraft();keepDraft();render();},'pos-step':el=>{const i=+el.dataset.index;ui.cart[i].qty+=+el.dataset.delta;if(ui.cart[i].qty<1)ui.cart.splice(i,1);dropEmptyDraft();keepDraft();render();},
  'pos-checkout':checkout,
  'confirm-checkout':()=>{valid();const payment={method:$('payment-method').value,received:+$('payment-received').value},number=currentDraft()?.number||peekTicket(S());return commit(()=>{const ticket=recordSale(S(),ui.cart,{reserve:ui.saleReserve!==false,note:ui.saleNote,customer:ui.posCustomer,payment,ticket:number});S().posDrafts=S().posDrafts.filter(d=>d.id!==ui.draftId);ui.cart=[];ui.draftId=null;ui.posCustomer='';ui.saleNote='';ui.saleReserve=true;return ticket;},ticket=>{render();showTicket(ticket);});},
  'view-ticket':el=>showTicket(ledgerSale(el.dataset.id)),
  'print-ticket':el=>{const t=ledgerSale(el.dataset.id);if(!t)throw Error('Ticket no disponible.');printDocument(ticketDocument(t,S().settings,saleReturns(S(),t.id)));},
  'export-ticket-html':async el=>{const t=ledgerSale(el.dataset.id);if(!t)throw Error('Ticket no disponible.');await downloadHtml(`${t.ticket||'3D-Woods-ticket'}.html`,standaloneDocument('Ticket '+(t.ticket||''),ticketDocument(t,S().settings,saleReturns(S(),t.id)),S().settings));},
  'export-ticket':async el=>{const t=ledgerSale(el.dataset.id),text=['3D-Woods',S().settings.businessName||'',t.ticket||t.id,new Date(t.date).toLocaleString('es-MX'),t.customer||'Venta al público','',...t.lines.map(l=>`${l.qty} x ${l.name} | ${money(l.unitPrice,t.currency)} | ${money(l.qty*l.unitPrice,t.currency)}`),'','TOTAL: '+money(t.total,t.currency),'Pago: '+(t.payment?.method||'Registro'),'Recibido: '+money(t.payment?.received??t.total,t.currency),'Cambio: '+money(t.payment?.change||0,t.currency),t.note||'','Comprobante de control interno. Sin valor fiscal.'].filter(v=>v!=='').join('\r\n');await storage.download(new Blob([text],{type:'text/plain;charset=utf-8'}),(t.ticket||'3D-Woods-ticket')+'.txt');},
  'return-sale':el=>returnDialog(el.dataset.id),
  'confirm-return':()=>{valid();const items=[...document.querySelectorAll('[data-return-line]')].map(el=>({lineIndex:+el.dataset.returnLine,qty:+el.value||0})).filter(x=>x.qty>0);return commit(()=>recordReturn(S(),{saleId:ui.returnSaleId,items,method:$('return-method').value,note:$('return-note').value}),t=>{render();showReturn(t);});},
  'view-return':el=>{const t=ledgerSale(el.dataset.id);if(t)showReturn(t);},
  'print-return':el=>{const t=ledgerSale(el.dataset.id),sale=ledgerSale(t?.saleId);if(!t)throw Error('Devolución no disponible.');printDocument(returnDocument(t,sale,S().settings));},
  'export-return-html':async el=>{const t=ledgerSale(el.dataset.id),sale=ledgerSale(t?.saleId);if(!t)throw Error('Devolución no disponible.');await downloadHtml(`${t.ticket||'devolucion'}.html`,standaloneDocument('Devolución '+t.ticket,returnDocument(t,sale,S().settings),S().settings));},
  'partial-cut':()=>openCut('partial'),'full-cut':()=>openCut('full'),
  'confirm-cut':el=>{const note=$('cut-note')?.value||'';const cut=recordCashCut(S(),{type:el.dataset.type,note});return commit(()=>cut,()=>{render();showCut(cut);});},
  'view-cut':el=>{const cut=S().cashCuts.find(c=>c.id===el.dataset.id);if(cut)showCut(cut);},
  'print-cut':el=>{const cut=S().cashCuts.find(c=>c.id===el.dataset.id);if(!cut)throw Error('Corte no disponible.');printDocument(cutDocument(cut,brand()));},
  'export-cut-html':async el=>{const cut=S().cashCuts.find(c=>c.id===el.dataset.id);if(!cut)throw Error('Corte no disponible.');await downloadHtml(`${cut.number}.html`,standaloneDocument('Corte '+cut.number,cutDocument(cut,brand()),brand()));}
 };
 async function change(el){
  if(el.id==='purchase-item'){const[kind,id]=el.value.split(':');purchaseDialog(kind,id);return true;}
  if(el.id==='stock-source'){const[b,o]=el.value.split('|'),object=S().boxes.find(x=>x.id===b)?.objects.find(x=>x.id===o);if(object){const calc=calculate(object,S().materials,S().settings);$('stock-name').value=object.name;$('stock-cost').value=calc.missing?0:calc.cost.toFixed(2);$('stock-price').value=calc.missing?0:calc.price.toFixed(2);}return true;}
  if(el.id==='production-qty'){if(!el.checkValidity())throw Error('Revisa la cantidad de producción.');const p=productionPlan(+el.value);$('production-plan').innerHTML=p.html;document.querySelector('[data-action="confirm-production"]').disabled=!p.ok;return true;}
  if(el.dataset.posQty!=null||el.dataset.posPrice!=null){if(!el.checkValidity())throw Error('Revisa cantidad o precio.');const key=el.dataset.posQty!=null?'qty':'unitPrice',index=+(el.dataset.posQty??el.dataset.posPrice);ui.cart[index][key]=+el.value;keepDraft();render();return true;}
  if(el.dataset.posColor!=null){const[index,slot]=el.dataset.posColor.split('|').map(Number),line=ui.cart[index];if(line){if(line.kind==='product')line.requestedColor=el.value;else{line.colors??=[];line.colors[slot]=el.value;}keepDraft();render();}return true;}
  if(el.id==='pos-customer'){ui.posCustomer=el.value;keepDraft();return true;}if(el.id==='pos-note'){ui.saleNote=el.value;keepDraft();return true;}if(el.id==='pos-reserve'){ui.saleReserve=el.checked;keepDraft();render();return true;}
  if(el.id==='payment-method'){const total=salePreview(S(),ui.cart,ui.saleReserve!==false).total;$('payment-received').readOnly=el.value!=='efectivo';if(el.value!=='efectivo')$('payment-received').value=total.toFixed(2);updateChange();return true;}
  return false;
 }
 function updateChange(){if(!$('payment-received'))return;const total=salePreview(S(),ui.cart,ui.saleReserve!==false).total,amount=+$('payment-received').value;$('payment-change').textContent=amount<total?'Faltan '+money(total-amount,S().currency):money(amount-total,S().currency);}
 document.addEventListener('input',e=>{
  if(e.target.id==='pos-search'){ui.posSearch=e.target.value;render();}
  if(e.target.id==='pos-customer'){ui.posCustomer=e.target.value;keepDraft();}
  if(e.target.id==='pos-note'){ui.saleNote=e.target.value;keepDraft();}
  if(e.target.id==='payment-received')updateChange();
 });
 document.addEventListener('click',e=>{const el=e.target.closest('[data-action="return-sale"]');if(el)ui.returnSaleId=el.dataset.id;},true);
 document.addEventListener('keydown',e=>{if(ui.view!=='pos'||document.getElementById('modal-root').childElementCount)return;if(e.key==='F2'){e.preventDefault();actions['new-sale']();}if(e.key==='F4'){e.preventDefault();try{checkout();}catch(err){toast(err.message,true);}}if(e.key==='Enter'&&e.target.id==='pos-search'){const match=document.querySelector('.pos-product');if(match){e.preventDefault();actions['pos-add'](match);}}});
 return {actions,change,isBusy:()=>busy,enterPOS};
}
